<script setup>
import { ref } from 'vue';
import { Download, Upload, ShieldCheck, DatabaseBackup, Languages, FileSpreadsheet, Info } from '@lucide/vue';
import { state, dispatch, notify, restoreBackup } from '../state';
import { storage, desktop } from '../storage';
import { exampleMode, studioStorageKey } from '../example-mode.mjs';
import { t, language, date, errorText } from '../i18n';
import { createDiagnostics } from '../../core/diagnostics.mjs';
import { exportOpenData } from '../../core/open-exports.mjs';
import { APP_VERSION as applicationVersion } from '../../core/version.mjs';
import { BACKUP_LIMIT } from '../../core/files.mjs';
import PageHeader from '../components/PageHeader.vue';
import FormField from '../components/FormField.vue';
import AppDialog from '../components/AppDialog.vue';
import CsvImportDialog from '../components/CsvImportDialog.vue';
import BackupControls from '../components/BackupControls.vue';
const diagnostics=ref(null);
const backupControls=ref(), exportFormat=ref('csv'), exporting=ref(false);
const showImport=ref(false),restore=ref(null),busy=ref(false),error=ref(''),fileInput=ref();
const lastBackupKey=studioStorageKey('ricamo-last-backup');
const lastBackup=ref(localStorage.getItem(lastBackupKey)||'');
async function setting(key,value){try{await dispatch('settings.save',{[key]:value});notify();}catch(caught){error.value=errorText(caught);}}
async function backup(){busy.value=true;error.value='';try{if(await storage.backup()){lastBackup.value=new Date().toISOString();localStorage.setItem(lastBackupKey,lastBackup.value);await backupControls.value?.refresh();notify();}}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function inspect(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>BACKUP_LIMIT)throw Object.assign(new Error(),{code:'file_too_large'});restore.value=await storage.inspectRestore(await file.text());}catch(caught){error.value=errorText(caught);}finally{busy.value=false;event.target.value='';}}
async function confirmRestore(){busy.value=true;try{await restoreBackup(restore.value.token);restore.value=null;}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function exportData(type){if(exporting.value)return;exporting.value=true;error.value='';const format=exportFormat.value;try{const data=exportOpenData(state.value,type,{format,language:language.value});if(await storage.saveFile({name:`ricamo-${type}.${format}`,data}))notify();}catch(caught){error.value=errorText(caught);}finally{exporting.value=false;}}
function inspectDiagnostics(){diagnostics.value=JSON.stringify(createDiagnostics(state.value,{storage:desktop?'sqlite':'indexeddb'}),null,2)}
async function saveDiagnostics(){if(exporting.value)return;exporting.value=true;error.value='';try{if(await storage.saveFile({name:'ricamo-diagnostics.json',data:diagnostics.value}))notify()}catch(caught){error.value=errorText(caught)}finally{exporting.value=false}}
</script>
<template>
  <div class="page"><PageHeader :eyebrow="t('settings')" :title="t('settingsTitle')" />
    <p v-if="error" class="notice error" role="alert">{{ error }}</p>
    <div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>{{ t('preferences') }}</h2><Languages :size="20" class="muted" /></div><div class="panel-body"><div class="form-grid"><FormField :label="t('language')" wide v-slot="{id}"><select :id="id" :value="state.settings.language" @change="setting('language',$event.target.value)"><option value="it">Italiano</option><option value="en">English</option></select></FormField><FormField :label="t('currency')" v-slot="{id}"><select :id="id" :value="state.settings.currency" @change="setting('currency',$event.target.value)"><option v-for="currency in ['EUR','GBP','USD','CHF','CAD','AUD','JPY','BRL']" :key="currency">{{ currency }}</option></select></FormField><FormField :label="t('paper')" v-slot="{id}"><select :id="id" :value="state.settings.paper" @change="setting('paper',$event.target.value)"><option value="a4">A4</option><option value="letter">Letter</option></select></FormField></div></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('backup') }}</h2><DatabaseBackup :size="20" class="muted" /></div><div class="panel-body"><p class="field-help">{{ t('backupHelp') }}</p><div class="stat-row"><span>{{ t('lastBackup') }}</span><span>{{ lastBackup?date(lastBackup):t('never') }}</span></div><div class="actions" style="margin-top:18px;flex-wrap:wrap"><button class="button primary" :disabled="busy" @click="backup"><Download :size="16" />{{ t('createBackup') }}</button><button class="button" :disabled="busy" @click="fileInput.click()"><Upload :size="16" />{{ t('restoreBackup') }}</button></div><input ref="fileInput" type="file" accept=".ricamobackup" class="sr-only" :aria-label="t('restoreBackup')" @change="inspect" /><p v-if="desktop" class="field-help" style="margin-top:16px">{{ t('automaticBackupHelp') }}</p><BackupControls v-if="desktop" ref="backupControls" /></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('data') }}</h2><FileSpreadsheet :size="20" class="muted" /></div><div class="panel-body"><p class="field-help">{{ t('importHelp') }}</p><FormField :label="t('openExportFormat')" v-slot="{id}"><select :id="id" v-model="exportFormat" :disabled="exporting"><option value="csv">CSV</option><option value="tsv">TSV</option><option value="json">JSON</option></select></FormField><p class="field-help">{{t('openExportHelp')}}</p><p v-if="exporting" class="field-help" role="status">{{t('openExportPreparing')}}</p><div class="actions" style="margin:18px 0;flex-wrap:wrap"><button class="button primary" @click="showImport=true"><Upload :size="16" />{{ t('importCsv') }}</button><button class="button" :disabled="exporting" @click="exportData('inventory')"><Download :size="16" />{{ t('openExportInventory') }}</button></div><div class="actions" style="flex-wrap:wrap"><button v-for="type in ['movements','projects','purchases']" :key="type" class="button small" :disabled="exporting" @click="exportData(type)">{{ t('export') }} · {{ t(type==='movements'?'history':type==='purchases'?'shopping':type) }}</button></div></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('about') }}</h2><Info :size="20" class="muted" /></div><div class="panel-body"><h3 style="font-family:Georgia,serif;font-size:25px;font-weight:400">Ricamo <span class="muted" style="font:12px 'Segoe UI',sans-serif">{{applicationVersion}}</span></h3><p class="notice"><ShieldCheck :size="20" />{{ t('privacy') }}</p><div class="actions form-section"><button class="button small" @click="inspectDiagnostics">{{t('diagnosticsTitle')}}</button></div><p class="field-help">{{ t('colorAttribution') }}</p><p class="field-help" style="margin-top:12px">Vue · Electron · SQLite · jsPDF · Lucide</p><p v-if="!desktop && !exampleMode" class="notice warning" style="margin-top:16px">{{ t('browserPreviewHelp') }}</p></div></section></div>
<AppDialog v-if="diagnostics" :title="t('diagnosticsTitle')" wide :busy="exporting" @close="diagnostics=null"><p class="notice">{{t('diagnosticsHelp')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><FormField :label="t('diagnosticsPreview')" v-slot="{id}"><textarea :id="id" :value="diagnostics" readonly rows="18" class="mono"/></FormField><template #footer><button class="button" :disabled="exporting" @click="diagnostics=null">{{t('close')}}</button><button class="button primary" :disabled="exporting" @click="saveDiagnostics"><Download :size="16"/>{{t('export')}}</button></template></AppDialog>
    <CsvImportDialog v-if="showImport" @close="showImport=false" />
    <AppDialog v-if="restore" :title="t('restoreBackup')" :busy="busy" @close="restore=null"><p v-if="error" class="notice error" role="alert">{{ error }}</p><p class="notice warning">{{ t('restoreWarning') }}</p><div class="stat-row"><span>{{ t('date') }}</span><strong>{{ date(restore.createdAt) }}</strong></div><div v-for="(value,key) in restore.summary" :key="key" class="stat-row"><span>{{ t(key==='attachments'?'files':key) }}</span><strong>{{ value }}</strong></div><template #footer><button class="button" :disabled="busy" @click="restore=null">{{ t('cancel') }}</button><button class="button primary" :disabled="busy" @click="confirmRestore">{{ t('restoreConfirm') }}</button></template></AppDialog>
  </div>
</template>
